    async function photoFiles(h,n=1,width=2,height=2){const png=await h.p.evaluate(({width,height})=>{const c=document.createElement('canvas');c.width=width;c.height=height;c.getContext('2d').fillRect(0,0,width,height);return c.toDataURL('image/png').split(',')[1];},{width,height});return Array.from({length:n},(_,i)=>({name:'synthetic-'+i+'.png',mimeType:'image/png',buffer:Buffer.from(png,'base64')}));}
    async function startPhoto(h,n=1){h.expectWrites(3);const req=h.hold('/shop/a/photo');await h.p.locator('#bqaPh').setInputFiles(await photoFiles(h,n));await req.seen;return req;}
